const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Farmland southeast of Calgary: approximate coordinates
  const geometry = ee.Geometry.Point([-113.8, 51.0]).buffer(1000); // 1km buffer
  const date1 = '2025-08-19';
  const date2 = '2025-08-24';

  // Function to get cloud-masked Sentinel-2 image for a date
  function getS2Image(date) {
    const startDate = ee.Date(date).advance(-1, 'day'); // ±1 day window
    const endDate = ee.Date(date).advance(1, 'day');

    let col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
                .filterBounds(geometry)
                .filterDate(startDate, endDate)
                .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));

    // Cloud masking using QA60 band
    function maskS2Clouds(image) {
      const qa = image.select('QA60');
      const cloudBitMask = 1 << 10;
      const cirrusBitMask = 1 << 11;
      const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                   .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
      return image.updateMask(mask);
    }

    col = col.map(maskS2Clouds);

    // Compute NDVI
    col = col.map(function(img) {
      const ndvi = img.normalizedDifference(['B8', 'B4']).rename('NDVI');
      return img.addBands(ndvi);
    });

    // Take median composite
    return col.select('NDVI').median();
  }

  // 2. Data Acquisition & Check
  let img1 = getS2Image(date1);
  let img2 = getS2Image(date2);

  // Check if collections are empty (size check on original collections)
  const col1 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
                 .filterBounds(geometry)
                 .filterDate(ee.Date(date1).advance(-1, 'day'), 
                            ee.Date(date1).advance(1, 'day'));
  const col2 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
                 .filterBounds(geometry)
                 .filterDate(ee.Date(date2).advance(-1, 'day'), 
                            ee.Date(date2).advance(1, 'day'));

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`${date1} Images: ${size1}`);
  console.log(`${date2} Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing: Check valid pixels
  const reducer = ee.Reducer.count().unweighted();
  const scale = 1000; // Use 1km scale for efficiency

  const count1 = img1.reduceRegion({
    reducer: reducer,
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const count2 = img2.reduceRegion({
    reducer: reducer,
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`${date1} Valid Pixels: ${count1}`);
  console.log(`${date2} Valid Pixels: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation: Mean NDVI
  const meanReducer = ee.Reducer.mean().unweighted();

  const mean1 = img1.reduceRegion({
    reducer: meanReducer,
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const mean2 = img2.reduceRegion({
    reducer: meanReducer,
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`${date1} Mean NDVI: ${mean1 ? mean1.toFixed(3) : 'null'}`);
  console.log(`${date2} Mean NDVI: ${mean2 ? mean2.toFixed(3) : 'null'}`);

  // 5. Validation & Final Answer
  // Check for invalid values (NDVI should be between -1 and 1)
  if (mean1 === null || mean2 === null || 
      isNaN(mean1) || isNaN(mean2) ||
      mean1 < -1 || mean1 > 1 || mean2 < -1 || mean2 > 1) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Determine if vegetation greenness decreased
  if (mean2 < mean1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
